/**
 * Accessor function returning normalized semester booklist
 */
function getDepartmentSyllabus(reg, deptId, semester) {
  const r = (reg === "2016" || reg === 2016) ? "2016" : "2022";
  const sem = Number(semester);

  if (SYLLABUS_DATA[r] && SYLLABUS_DATA[r][deptId] && SYLLABUS_DATA[r][deptId][sem]) {
    return SYLLABUS_DATA[r][deptId][sem];
  }

  // Safe fallback if an unrecognized id is provided
  if (SYLLABUS_DATA[r] && SYLLABUS_DATA[r]["rac"] && SYLLABUS_DATA[r]["rac"][sem]) {
    return SYLLABUS_DATA[r]["rac"][sem];
  }

  return [];
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { TECHNOLOGIES_DATA, SYLLABUS_DATA, getDepartmentSyllabus };
}
